<?php
require_once 'includes/db.php'; require_once 'includes/functions.php'; require_admin(); $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$role=$_POST['role']??'student';$studentId=($_POST['student_id']??'')!==''?(int)$_POST['student_id']:null;
 if($name==='')$errors[]='Full name is required.';if(!preg_match('/^[A-Za-z0-9_.-]{4,60}$/',$username))$errors[]='Username must be 4–60 characters using letters, numbers, dot, underscore or hyphen.';if(!valid_email($email))$errors[]='Enter a valid email address.';if(strlen($password)<10)$errors[]='Password must be at least 10 characters.';if(!in_array($role,['admin','student'],true))$errors[]='Select a valid role.';if($role==='student'&&$studentId===null)$errors[]='Link a student account to a student record.';
 if(!$errors){try{$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conn->prepare('INSERT INTO app_users(full_name,username,email,password_hash,role,student_id) VALUES(?,?,?,?,?,?)');$stmt->bind_param('sssssi',$name,$username,$email,$hash,$role,$studentId);$stmt->execute();flash('User account created successfully.');header('Location: users.php');exit;}catch(Throwable $e){$errors[]='Could not create account. Username/email may already exist, or the selected student may be invalid.';}}
}
if(isset($_GET['delete'])&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$uid=(int)$_GET['delete'];if($uid===(int)$_SESSION['user']['user_id'])flash('You cannot delete the account you are currently using.','error');else{$stmt=$conn->prepare('DELETE FROM app_users WHERE user_id=?');$stmt->bind_param('i',$uid);$stmt->execute();flash('User account deleted.');}header('Location: users.php');exit;}
$pageTitle='User accounts';require 'includes/header.php';$users=$conn->query('SELECT user_id,full_name,username,email,role,student_id,created_at FROM app_users ORDER BY user_id DESC');$students=$conn->query('SELECT student_id,reg_no,first_name,last_name FROM student ORDER BY reg_no'); ?>
<div class="page-heading"><div><h1>User accounts</h1><p class="subheading">Create login accounts and assign administrator or student access.</p></div></div>
<div class="card"><h2>Create user account</h2><?php if($errors): ?><div class="alert error"><ul><?php foreach($errors as $er): ?><li><?= e($er) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-grid"><div class="field"><label>Full name *</label><input name="full_name" required maxlength="100" value="<?= e($_POST['full_name']??'') ?>" placeholder="Full name"></div><div class="field"><label>Username *</label><input name="username" required pattern="[A-Za-z0-9_.-]{4,60}" value="<?= e($_POST['username']??'') ?>" placeholder="username"></div><div class="field"><label>Email *</label><input type="email" name="email" required value="<?= e($_POST['email']??'') ?>" placeholder="name@example.com"></div><div class="field"><label>Password (minimum 10 characters) *</label><input type="password" name="password" minlength="10" required autocomplete="new-password" placeholder="Strong password"></div><div class="field"><label>Role *</label><select name="role"><option value="student">Student</option><option value="admin">Administrator</option></select></div><div class="field"><label>Linked student record (required for student)</label><select name="student_id"><option value="">Choose student</option><?php while($s=$students->fetch_assoc()): ?><option value="<?= (int)$s['student_id'] ?>"><?= e($s['reg_no'].' — '.$s['first_name'].' '.$s['last_name']) ?></option><?php endwhile; ?></select></div></div><button class="btn">Create account</button></form></div>
<div class="card"><h2>Existing accounts</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>Student ID</th><th>Created</th><th>Action</th></tr></thead><tbody><?php while($u=$users->fetch_assoc()): ?><tr><td><?= e($u['full_name']) ?></td><td><?= e($u['username']) ?></td><td><?= e($u['email']) ?></td><td><span class="badge"><?= e(ucfirst($u['role'])) ?></span></td><td><?= e($u['student_id']??'—') ?></td><td><?= e($u['created_at']) ?></td><td><?php if((int)$u['user_id']!==(int)$_SESSION['user']['user_id']): ?><form method="post" class="inline-form" action="users.php?delete=<?= (int)$u['user_id'] ?>" onsubmit="return confirm('Delete this account?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn danger small">Delete</button></form><?php else: ?><span class="hint">Current user</span><?php endif; ?></td></tr><?php endwhile; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>